/** Auto-generated from games/manifest.json. Steam fields merge from games/steam-meta.json. */
import steamMeta from '../games/steam-meta.json'

export type CoverVibe = 'cozy' | 'neon' | 'epic' | 'souls' | 'arcade'

export type CoverMeta = {
  id: string
  file: string
  titleZh: string
  titleEn: string
  blurb: string
  source: string
  type: 'steam-store-art' | 'stylized-placeholder'
  vibe: CoverVibe
  tags?: string[]
  review?: string
  reviewCount?: number
  year?: number
}

type SteamMetaEntry = {
  appid?: number
  tags?: string[]
  review?: string
  reviewCount?: number
  year?: number
}

const STEAM_META = steamMeta as Record<string, SteamMetaEntry>

function attachSteam(cover: CoverMeta): CoverMeta {
  const meta = STEAM_META[cover.id]
  if (!meta) return cover
  const next: CoverMeta = { ...cover }
  const tags = (meta.tags ?? []).map((tag) => tag.trim()).filter(Boolean).slice(0, 4)
  if (tags.length) next.tags = tags
  if (meta.review && typeof meta.reviewCount === 'number' && meta.reviewCount > 0) {
    next.review = meta.review
    next.reviewCount = meta.reviewCount
  }
  if (typeof meta.year === 'number') next.year = meta.year
  return next
}

